function wfcTiles(){
  return {
    names:['sea','sand','grass','forest','rock'],
    colors:{ sea:'#22D3EE', sand:'#F5A623', grass:'#10B981', forest:'#0B7A55', rock:'#71717A' },
    adj:{
      sea:['sea','sand'],
      sand:['sea','sand','grass'],
      grass:['sand','grass','forest'],
      forest:['grass','forest','rock'],
      rock:['forest','rock']
    }
  };
}
function wfcRng(seed){
  var t=seed>>>0;
  return function(){
    t += 0x6D2B79F5;
    var r=Math.imul(t ^ (t>>>15), 1|t);
    r = (r + Math.imul(r ^ (r>>>7), 61|r)) ^ r;
    return ((r ^ (r>>>14))>>>0)/4294967296;
  };
}
function wfcRun(w, h, seed){
  var T=wfcTiles(), rng=wfcRng(seed), N=T.names, i;
  var cells=[];
  for(i=0;i<w*h;i++) cells.push(N.slice());
  function propagate(idx){
    var stack=[idx];
    while(stack.length){
      var cur=stack.pop(), cx=cur%w, cy=Math.floor(cur/w);
      var allowed={};
      for(var a=0;a<cells[cur].length;a++){
        var opts=T.adj[cells[cur][a]];
        for(var b=0;b<opts.length;b++) allowed[opts[b]]=1;
      }
      var nbs=[];
      if(cx>0) nbs.push(cur-1);
      if(cx<w-1) nbs.push(cur+1);
      if(cy>0) nbs.push(cur-w);
      if(cy<h-1) nbs.push(cur+w);
      for(var k=0;k<nbs.length;k++){
        var nb=nbs[k], before=cells[nb].length;
        cells[nb]=cells[nb].filter(function(t){ return allowed[t]; });
        if(!cells[nb].length) return false;
        if(cells[nb].length<before) stack.push(nb);
      }
    }
    return true;
  }
  for(var step=0;step<w*h;step++){
    var best=-1, bestE=1e9;
    for(i=0;i<w*h;i++) if(cells[i].length>1 && cells[i].length<bestE){ bestE=cells[i].length; best=i; }
    if(best<0) break;
    var pick=cells[best][Math.floor(rng()*cells[best].length)];
    cells[best]=[pick];
    if(!propagate(best)) return { error:'坍缩矛盾（种子 '+seed+'）', grid:null };
  }
  var grid=[];
  for(var y=0;y<h;y++){
    var row=[];
    for(var x=0;x<w;x++) row.push(cells[y*w+x][0]);
    grid.push(row);
  }
  return { error:null, grid:grid };
}
function wfcValidate(grid){
  var T=wfcTiles(), h=grid.length, w=grid[0].length;
  function okPair(a,b){ return T.adj[a].indexOf(b)>=0; }
  for(var y=0;y<h;y++) for(var x=0;x<w;x++){
    if(x+1<w && !okPair(grid[y][x],grid[y][x+1])) return false;
    if(y+1<h && !okPair(grid[y][x],grid[y+1][x])) return false;
  }
  return true;
}
function wfcSvg(grid){
  var T=wfcTiles(), h=grid.length, w=grid[0].length, C=22;
  var s='<svg xmlns="http://www.w3.org/2000/svg" width="'+(w*C)+'" height="'+(h*C)+'" viewBox="0 0 '+(w*C)+' '+(h*C)+'">';
  for(var y=0;y<h;y++) for(var x=0;x<w;x++)
    s+='<rect x="'+(x*C)+'" y="'+(y*C)+'" width="'+C+'" height="'+C+'" fill="'+T.colors[grid[y][x]]+'" stroke="#0A0A0B" stroke-width="1"/>';
  return s+'</svg>';
}
function wfcCounts(grid){
  var out={};
  for(var y=0;y<grid.length;y++) for(var x=0;x<grid[0].length;x++) out[grid[y][x]]=(out[grid[y][x]]||0)+1;
  return out;
}
if (typeof module !== 'undefined' && module.exports) {
  module.exports = { wfcTiles:wfcTiles, wfcRng:wfcRng, wfcRun:wfcRun, wfcValidate:wfcValidate, wfcSvg:wfcSvg, wfcCounts:wfcCounts };
}
if (typeof window !== 'undefined') {
  window.WfcForgePure = { wfcTiles:wfcTiles, wfcRng:wfcRng, wfcRun:wfcRun, wfcValidate:wfcValidate, wfcSvg:wfcSvg, wfcCounts:wfcCounts };
}
